    NC_GLOBAL {
        String jma_data_provider "Japan Meteorological Agency (JMA)";
        String jma_data_provider_url "https://www.jma.go.jp/jma/indexe.html";
        String jma_data_provider_address "3-6-9 Toranomon, Minato City, Tokyo 105-8431, Japan";
        String jma_data_provider_email "<jra@met.kishou.go.jp>";
        String jma_data_title "Japanese Reanalysis for Three Quarters of a Century (JRA-3Q)";
        String jma_data_abstract "JMA is currently conducting the Japanese Reanalysis for Three Quarters of a Century (JRA-3Q), which covers the period from September 1947 onward to extend the current period of data coverage and improve the quality of long-term reanalysis. The project involves a sophisticated data assimilation system (based on the operational set-up as of December 2018) incorporating development results from the operational NWP system and sea surface temperature analysis achieved since JRA-55 (based on the operational set-up as of December 2009). New datasets of past observations are also assimilated, including rescued historical observations and reprocessed satellite data supplied by meteorological and satellite centers worldwide. Many of the deficiencies of JRA-55 are alleviated in JRA-3Q, providing a high-quality homogeneous reanalysis dataset that covers the previous 75 years.";
        String jma_data_url "https://jra.kishou.go.jp/JRA-3Q/index_en.html";
        String jma_data_group "Model level analysis fields (anl_mdl)";
